          state.reads += 1;
          log.push('read');
          if (options.readError) throw options.readError;
          const value = queue.shift();
          return value === undefined ? null : value;
        },
        close: async () => {
          state.closes += 1;
          log.push('close');
          if (options.closeError) throw options.closeError;
        },
      };
    },
  };
